INSERT INTO public.personas (id, name, role, blurb, practice_area, gender, source_type, personality_traits, known_objections)
VALUES
('guarded-ops-director','Alex Ferris','Guarded Ops Director','No context for the call, no patience for a wind-up. Wants to know why you are calling in the first five seconds or the call is over. Not rude, just protective of time.','hubspot','male','composite','Protective of time, blunt, skeptical of vendors. Softens only if the rep gives a real, specific reason for the call.','"Who is this?" / "I''m in the middle of something" / "How did you get this number?" / "We''re not looking at anything right now."'),
('friendly-busy-marketing-lead','Nora Bianchi','Friendly-but-Busy Marketing Lead','Warm because of an existing connection (referral or event), but juggling too much to commit to anything without a clear, low-effort reason.','hubspot','female','composite','Warm, agreeable, chronically overbooked. Says yes fast to a small, specific ask; stalls indefinitely on anything that sounds like a project.','"Send me something and I''ll look at it" / "Now is not a great time of year" / "I''d have to loop in a few people."'),
('distracted-opted-in','Casey Odom','Distracted, Forgot They Opted In','Filled out a form weeks ago and forgot about it entirely. Mildly annoyed at first, softens once reminded what they actually signed up for.','hubspot','female','composite','Distracted, initially short and suspicious, guarded about being sold to twice. Relaxes when given calm, specific context.','"I don''t remember signing up for anything" / "How did you get my info?" / "I''m not really looking for a sales pitch."')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.scenarios (name, practice_area, call_type, difficulty, duration_minutes, rubric, featured, persona, goal, scenario, topics, created_by_hint)
VALUES
('BDR — Website Visitor / Intent Signal Cold Call','hubspot','discovery','realistic',5,'business_development',false,
 'Alex Ferris — Guarded Ops Director. No context for the call, no patience for a wind-up. Wants to know why you are calling in the first five seconds or the call is over. Not rude, just protective of time. Softens only if the rep gives a real, specific reason for the call.',
 'Open the call referencing the site visit without overstating what it means, earn 60 seconds of genuine attention, and book a follow-up call. No package pitch: the only ask is time on the calendar.',
 'Alex''s company showed up in SmartBug''s website visitor tracking, viewing a few pages related to AI tools and HubSpot services. Alex has no idea this was tracked and did not fill out any form. Alex is in the middle of a busy day and picks up expecting a vendor cold call. If the rep opens with something generic ("just checking in") or acts like the visit proves clear buying intent, Alex will shut the call down quickly. If the rep is upfront and specific about why they''re calling, Alex will engage briefly.',
 'Business Development / BDR. What to focus on: No specific service is being pitched. Focus on opening without overclaiming what the website visit means (a visit isn''t a stated need), giving a real, non-generic reason for the call, asking one qualifying question about what brought them to the site, and closing for a specific meeting time rather than a vague "let''s stay in touch." Watch for reps who lead with a full pitch instead of a hook.',
 'BDR content pack'),
('BDR — Job-Posting / Tech-Stack Signal Cold Call','hubspot','discovery','realistic',5,'business_development',false,
 'Alex Ferris — Guarded Ops Director. No context for the call, no patience for a wind-up. Wants to know why you are calling in the first five seconds or the call is over. Not rude, just protective of time. Softens only if the rep gives a real, specific reason for the call.',
 'Reference the job posting as the reason for the call, ask one question that surfaces why the role is open, and book a discovery call. No package pitch.',
 'Alex''s company recently posted an open role, either a dedicated HubSpot Administrator or a Marketing Ops Manager whose responsibilities include owning HubSpot. The rep found this through normal prospecting research, not through Alex''s company reaching out. Alex is used to recruiters and vendors finding this posting and calling about it, so they''re primed to hang up fast on anything generic. If the rep''s opener sounds templated or doesn''t tie back to something specific about the role, Alex disengages. A rep who asks a genuine question about the hiring need, and reads the role correctly (admin hire versus a broader ops hire), gets a real, if brief, answer.',
 'Business Development / BDR. What to focus on: Using a public hiring signal as the reason for the call, without assuming the exact pain point. The posting could be a dedicated HubSpot Administrator role or a broader Marketing Ops Manager role that includes owning HubSpot, so the rep needs to read the posting and adjust the framing accordingly. Practice a specific, researched opener ("saw you''re hiring for X") and one sharp qualifying question about what''s driving the hire. End with a clear ask for a short call, not a project pitch.',
 'BDR content pack'),
('BDR — Referral / Warm Intro Cold Call','hubspot','discovery','easy',5,'business_development',false,
 'Nora Bianchi — Friendly-but-Busy Marketing Lead. Warm because of an existing connection (referral or event), but juggling too much to commit to anything without a clear, low-effort reason. Will say yes to a meeting fast if the ask is small and specific.',
 'Open by naming the referral, give one clear reason the call is worth Nora''s time, and book a meeting. No package pitch.',
 'A mutual contact, an existing SmartBug client, mentioned Nora''s company might be a good fit and passed along her name. Nora trusts the source of the referral and will give the rep a genuine hearing, but she''s stretched across several campaigns and won''t commit to anything that sounds like it requires real time investment right now. If the rep only leans on the referral without giving Nora a real reason to act, she''ll be polite but noncommittal. A specific, small ask gets a yes.',
 'Business Development / BDR. What to focus on: Using the referral for credibility early, without leaning on it as the entire pitch. Practice naming the connection clearly, giving one sentence on why the call is worth Nora''s time beyond the referral, and closing with a specific, low-effort ask.',
 'BDR content pack'),
('BDR — Event Follow-Up Cold Call (INBOUND)','hubspot','discovery','easy',5,'business_development',false,
 'Nora Bianchi — Friendly-but-Busy Marketing Lead. Warm because of an existing connection (referral or event), but juggling too much to commit to anything without a clear, low-effort reason. Will say yes to a meeting fast if the ask is small and specific.',
 'Reconnect using a specific detail from the INBOUND conversation, not a generic callback, and book a follow-up call.',
 'Nora stopped by SmartBug''s booth at INBOUND this year and spoke briefly with a member of the SmartBug team about AI tools in HubSpot. The conversation was short but genuine, she doesn''t remember every detail but recalls it was worthwhile. She''s now back to a packed schedule and hasn''t followed up herself. If the rep treats this like a cold call and re-explains everything from zero, Nora will feel like the booth conversation didn''t matter. If the rep references something specific from that exchange, she reengages warmly.',
 'Business Development / BDR. What to focus on: Referencing something specific from the INBOUND conversation (not a generic "great meeting you"), building on that specific moment rather than restarting the pitch from scratch, and closing with a concrete next step.',
 'BDR content pack'),
('BDR — Stale Re-engaged Inbound Lead Call','hubspot','discovery','hard',5,'business_development',false,
 'Casey Odom — Distracted, Forgot They Opted In. Filled out a form weeks ago and forgot about it entirely. Mildly annoyed at first ("who is this and how did you get my number"), softens once reminded what they actually signed up for. Guarded about being sold to twice.',
 'Reestablish context calmly when Casey doesn''t remember opting in, avoid sounding defensive, and re-earn a specific next step.',
 'Casey filled out a form on SmartBug''s site weeks ago after a passing moment of interest, then got busy and forgot entirely. No one from SmartBug followed up in time, so the lead went cold. Casey picks up mid-task and is initially short, half-suspecting this is an unsolicited sales call. If the rep gets flustered or over-apologizes when Casey doesn''t remember, Casey loses confidence in the call. If the rep calmly reminds Casey what they signed up for and gives a clear reason to talk now, Casey relaxes and reengages.',
 'Business Development / BDR. What to focus on: Recovering credibility once Casey pushes back with "I don''t remember signing up for this." Practice reminding Casey of the original form fill without being defensive or over-apologizing, and re-establishing a reason to talk now.',
 'BDR content pack');